window.RP_SESSION={"id":"S-05ed67ce565b","messages":[{"id":"RP-II-0165819","time":"2026-08-24T10:13:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"킁킁킁... 킁킁킁...\n\n길드 주변을 발발거리며, 열심히 냄새를 맡는 햄스터 한 마리. 아니, 햄스터라기엔 너무 크군요. 햄스터 데미간입니다.\n\n짐 보따리와 허리춤의 쌍권총이 인상깊군요. 그리고 도적으로 오해받지 않도록 하얀색 깃발을 들고 있습니다.","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165820","time":"2026-08-24T12:00:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 어휴 넌 그냥 쥐다 쥐. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165821","time":"2026-08-24T12:01:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 좀 사람답게 살어보란 말야. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165822","time":"2026-08-24T12:03:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"잉, 비슷하게 생겼군. 반갑다!\"\n\n두 발로 일어서서는, 손을 흔듭니다.\n\n\"여기가 어설픈 용맹 맞냐?!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165823","time":"2026-08-24T12:04:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 아니. 여긴 호박 농민 조합의 페퍼씨와 호박씨들 클랜이야. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165825","time":"2026-08-24T12:07:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"뭣. 호박씨?\"\n\n화들짝 놀라 잘못 들었나 의심합니다.\n\n\"지도를 잘못 봤나...\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165826","time":"2026-08-24T12:07:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 허이구. 기가 차네 기가 차. 어설픈 용맹 맞아 -- \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165827","time":"2026-08-24T12:10:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"잉? 거짓말을 하다니!\"\n\n속았다고 생각하고는,(그리고 실제로 속았지만) 부들부들 떠네요.\n\n\"후... 하지만 난 자비로운 햄스터니까 넘어가겠어.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165828","time":"2026-08-24T12:10:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"어설픈 용맹은 신입을 속이는 전통이 있나?\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165829","time":"2026-08-24T12:12:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 너 어디 마을 출신이야? --^ \"\n\n숀은 큰 귀를 한 번 팔랑거리며 물었습니다.\n\n쥐 데미간이라... 우린 마을 밖으로 나오는 일이 드뭅니다. 보수적인 무리 사회를 추구했으니까요.\n\n케닌은 이전 무리에서 추방 당해 정착한 것 같지만...\n\n킁킁킁.\n\n숀의 코가 움찔거렸습니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165830","time":"2026-08-24T12:15:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"해바라기 마을에서 왔지. 제일 큰 풍차집의 햄 주니어다!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165831","time":"2026-08-24T12:17:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 뭐? 선플라워 타운...? 그게 어디지...? \"\n\n엘모스? 록헤이븐? 아이비데일? 가만있자... 스프러스틱의 위성 마을인가? 아님...\n\n\" 아 혹시, 골드햄프셔 출신인가? 뭐 암튼... 일단 반갑다. 근데 혹시, 너도 쫒겨나서 온 건 아니쥐? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165832","time":"2026-08-24T12:18:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"땀을 삐질삐질 흘리면서 성벽 보수 공사에서 돌아오는 아키라. 다른 사람이랑은 별로 안 친하지만 (아마도) 머챈트와 숀과는 인사 정도 하는 사이입니다.\n\n\"남쪽 발의 숀.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165833","time":"2026-08-24T12:18:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아닛, 또다른 쥐가?","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165834","time":"2026-08-24T12:18:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"뭣, 우리마을이 얼마나...\"\n\n그다지 유명한 마을은 아니라는 걸 깨달은 햄쥐\n\n\"크흠. 쫒겨나? 아니! 이 몸은 제 발로 나왔다는 말씀.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165835","time":"2026-08-24T12:19:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"낯선 이다. 누구지?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165836","time":"2026-08-24T12:19:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"남쪽 발의 숀, 네 자식인가?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165837","time":"2026-08-24T12:20:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 뭔 자식 인마 --; 너는 나랑 쟤가 같아보이냐? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165838","time":"2026-08-24T12:20:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165839","time":"2026-08-24T12:20:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아키라는 반쯤 걸레짝이 된 땀수건을 어깨에 걸칩니다.\n\n\"털 색 다르다. 하지만 아내의 털 색일 수도 있다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165840","time":"2026-08-24T12:20:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"붐.","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165841","time":"2026-08-24T12:21:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165842","time":"2026-08-24T12:21:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"붐!","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165843","time":"2026-08-24T12:21:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"자식 아니라면… 동족? 하지만 살 많이 쪄있다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165844","time":"2026-08-24T12:22:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그런거 아냐. 그냥 쟤도 나와 비슷한 동족인거쥐. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165845","time":"2026-08-24T12:22:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"음, 오니와 큰 티플링. 헷갈리는 사람 있다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165846","time":"2026-08-24T12:23:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"대충 이해한 듯싶습니다. 그녀는 털이 노랗고 더 작고 뚱뚱한 버전의 숀을 내려다보았습니다.\n\n\"숀과 유사한 데미간아, 여기서 뭐하는 거지?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165847","time":"2026-08-24T12:24:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"킁킁킁...\n\n나이는 20년 정도 되었구만.\n\n\" 어이, 선플라워의 햄-주니어. 이름이 뭐야? 난 마우스가드의 숀이야. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165848","time":"2026-08-24T12:25:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"나, 아키라 베르데미켄이다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165849","time":"2026-08-24T12:25:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"세테니오라 부족 출신.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165850","time":"2026-08-24T12:44:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"이름? 아까 너 입으로 말했잖아? 햄 주니어다.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165851","time":"2026-08-24T12:44:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네 이름, 해무?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165852","time":"2026-08-24T12:45:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고 가문 이름, 주니오르?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165853","time":"2026-08-24T12:45:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아키라는 속으로 육즙이 줄줄 흐르는 큰 햄과 작은 햄을 상상했답니다.","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165854","time":"2026-08-24T12:55:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그래. 햄 주니어. 근데, 길드에 들어오려고? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165855","time":"2026-08-24T12:56:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"당연하지!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165856","time":"2026-08-24T12:57:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"호오?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165857","time":"2026-08-24T12:59:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아키라는 팔짱을 꼈습니다.\n\n\"우리 기루도, 위험한 일 많이 나간다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165858","time":"2026-08-24T13:01:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"해무처럼 작고 약하면 어렵다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165859","time":"2026-08-24T13:03:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 요 덩치는 신경 꺼도 돼. 지능이 다 가슴으로 갔으니까 --; \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165860","time":"2026-08-24T13:04:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 보아하니 싸움 경험이 없어보이쥔 않는데... 전에도 길드에서 활동한 적 있어? 아님 마우스가드였다든가. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165861","time":"2026-08-24T13:05:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그건 틀렸다, 내 머리는 두 주먹으로 갔다!\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165862","time":"2026-08-24T13:08:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"크흠... 아니, 여기가 첫 길드다! 하지만 총은 많이 연습했으니 괜찮을 거다!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165863","time":"2026-08-24T13:12:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 흠, 그래? 좋아. 그럼 내가 추천서를 하나 써주쥐. 떠돌이도 아녔고, 쥐 데미간 마을에서 지냈다니 '꼬리 규율' 정도는 알고 있겠쥐. \"\n\n꼬리 규율?","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165864","time":"2026-08-24T13:13:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"우리는 그런 거 모르는데...?\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165865","time":"2026-08-24T13:13:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"그의 꼬리는 너무 짧아서 보이지도 않을 지경입니다.","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165866","time":"2026-08-24T13:13:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165867","time":"2026-08-24T13:14:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"쥐 데미간 마을이면… 남쪽 발 숀, 네 이웃인가?\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165868","time":"2026-08-24T13:14:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 뭣...? 꼬리 규율을 모른다고? 마을 어르신들이 그런 얘기 안했어? 뭐, 뭐 '꼬리를 가진 자는 꼬리를 가진 자를 저버리지 않는다' 하는 그런... \"\n\n꼬리 규율은 쥐 데미간들이 지닌 공통적인 규율이자 전통 풍습 였습니다.\n\n\" 모른다고? 전-혀? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165869","time":"2026-08-24T13:16:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그런 멋진 규율이 있었다니, 지금부터라도 지켜야겠는걸?\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165870","time":"2026-08-24T13:17:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 아니. 모든 동족이 이웃인건 아냐. 물론 쥐 데미간들의 하이 클란인 록헤이븐에서 왈가왈부하쥐만, 사실 모든 쥐 데미간들이 아는 것도 아니고... 그냥 시시콜콜한 족보 놀이같은거쥐. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165871","time":"2026-08-24T13:18:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"구렇구만...\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165872","time":"2026-08-24T13:19:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"긁적...\n\n숀은 햄주니어를 보며 귀 뒤를 벅벅 긁었습니다.\n\n\" 뭐 됐다. 꼬리 규율은 이제 너무 오래된 전통이니까. 무튼 추천서는 써줄게, 근데 \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165873","time":"2026-08-24T13:19:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 쪽팔리는 짓은 하쥐마라. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165874","time":"2026-08-24T13:19:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"으하하하!\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165875","time":"2026-08-24T13:19:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"남쪽 발 숀, 걱정한다!\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165876","time":"2026-08-24T13:20:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 당근 걱정되짐마 --; 안 그래도 케닌 그 녀석 때문에 창피할 쥐경이라고. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165877","time":"2026-08-24T13:20:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 이번엔 골칫거리가 늘쥐 않길... \"","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165878","time":"2026-08-24T13:20:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"당연하지. 추천인 이름에 먹칠하진 않겠어. 심지어 같은 쥐 데미간을!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165879","time":"2026-08-24T13:21:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"걱정마라. 골쥣거리, 내가 단련시키겠다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165880","time":"2026-08-24T13:21:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아키라는 영 불길하게 씩 웃었습니다.","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165881","time":"2026-08-24T13:23:00+09:00","room":"RP II","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"단련...? 머 알겠다.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-II-0165882","time":"2026-08-24T13:24:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"골쥣거리ㅋㅋㅋㅋ","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165883","time":"2026-08-24T13:36:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"좋다! 그럼 나, 추천장이란 거 쓴다.\"","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165884","time":"2026-08-24T13:37:00+09:00","room":"RP II","name":"아키라 베르데미켄","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그렇게 스텔라는 다소 꼬불꼬불한 글씨로 쓰인 추천장도 같이 받게 되었습니다.","characters":["P-ee0c9d156dde"]},{"id":"RP-II-0165886","time":"2026-08-24T14:05:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0165887","time":"2026-08-24T14:05:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
